-- ============================================
-- Les 390 anomalies de source de culture_alsace, matérialisées (07/09/2026)
-- ============================================
-- CLAUDE.md, campagne 3 : « 390 coquilles de source copiées verbatim et
-- signalées, jamais corrigées (règle 1) », et plus loin « liste finie : elles ne
-- partent jamais dans un lot de publication ».
--
-- Cette liste n'existait nulle part. Ni dans le JSONL (aucun champ de
-- signalement), ni dans le dépôt : elle n'a vécu que dans le rapport d'une carte
-- Hermes, perdu. « Elles ne partent jamais dans un lot » était donc une
-- intention que rien n'appliquait — on ne peut pas exclure ce qu'on ne sait pas
-- nommer.
--
-- Reconstituée le 07/09/2026 en rejouant le parseur du studio
-- (scripts/extract/culture_alsace/lexique_a_d.py, branche data) sur les 73 pages
-- brutes archivées. Contrôles :
--   * le JSONL régénéré est identique octet à octet à celui du dépôt (23 851
--     lignes, même md5 une fois les fins de ligne normalisées) — le rapport
--     décrit donc bien les données réellement en base ;
--   * les 390 références se rattachent toutes à une attestation existante
--     (390/390, 386 attestations distinctes — quelques lignes portent deux
--     anomalies) ;
--   * aucune ne concerne une attestation déjà publiée dans une entrée.
--
-- Le rapport imprimé par le parseur PLAFONNE À 80 anomalies (« … et N autres »).
-- La liste complète a donc été prise en important le module et en rappelant
-- parse_page() page par page, jamais en lisant sa sortie — un plafond
-- d'affichage lu comme un total aurait donné 80 coquilles au lieu de 390.
--
-- Trois types, de gravité inégale :
--   * separateur_tete_non_standard (323) — le « .- » qui sépare la tête de
--     l'équivalent manque ou est coquillé. Le français et l'alsacien extraits
--     restent le plus souvent justes : c'est un signal de parsing.
--   * parenthese_non_fermee (37) — « (la » sans fermeture, qui affecte le
--     contexte.
--   * alsacien_finissant_par_separateur (30) — le plus grave : la forme
--     alsacienne elle-même porte un « .- » parasite (« d'Schofgarwe.- »).
--
-- Rien n'est corrigé ici (règle 1) : la table SIGNALE, elle ne réécrit pas.

CREATE TABLE IF NOT EXISTS public.anomalies_source (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  reference TEXT NOT NULL,
  type TEXT NOT NULL,
  detail TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (reference, type)
);

COMMENT ON TABLE public.anomalies_source IS
  'Défauts observés dans une source et copiés verbatim (règle 1) : la table les signale à l''arbitre, elle ne corrige rien. Clé de rattachement : attestations.reference. Reconstituée en rejouant le parseur du studio, jamais saisie à la main.';

CREATE INDEX IF NOT EXISTS ix_anomalies_source_reference
  ON public.anomalies_source (reference);

ALTER TABLE public.anomalies_source ENABLE ROW LEVEL SECURITY;

-- Même régime que attestations : le brut ne sort pas pour un visiteur.
DROP POLICY IF EXISTS anomalies_source_lecture_admin ON public.anomalies_source;
CREATE POLICY anomalies_source_lecture_admin ON public.anomalies_source
  FOR SELECT TO authenticated
  USING (public.is_admin());

-- Idempotent : rejouer la migration ne duplique rien et ne perd rien.
ON CONFLICT (reference, type) DO UPDATE SET detail = EXCLUDED.detail;

-- ============================================
-- anomalies_de() : le signalement d'une attestation, prêt à joindre
-- ============================================
-- Appelée depuis candidats_arbitrage() et detail_candidat()
-- (20260907020000) pour poser le signalement dans chaque variante, sans y
-- recopier une sous-requête. NULL quand la référence est saine — l'immense
-- majorité des cas.

CREATE OR REPLACE FUNCTION public.anomalies_de(p_reference TEXT)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT jsonb_agg(jsonb_build_object('type', a.type, 'detail', a.detail) ORDER BY a.type)
  FROM public.anomalies_source a
  WHERE p_reference IS NOT NULL AND a.reference = p_reference;
$fn$;

COMMENT ON FUNCTION public.anomalies_de(TEXT) IS
  'Anomalies de source rattachées à une attestation, par sa référence, ou NULL. SECURITY DEFINER parce qu''elle est appelée depuis les fonctions d''arbitrage, elles-mêmes réservées aux admins par is_admin() : le brut ne devient pas lisible pour autant.';
